import SwiftUI

/// Brand artwork from the Trackdown brand sheet.
///
/// Both images are vector assets in `Images.xcassets` with a light and a dark variant, and follow
/// the system appearance. Add `.resizable()` and `.scaledToFit()` to draw them at any size.
/// The SVGs are generated by `scripts/generate-brand-assets.swift`.
public enum TrackdownImage {
    /// The track mark followed by the "Trackdown" wordmark, 496 x 68 pt at 1x.
    public static let logo = Image("Logo", bundle: .module, label: Text("Trackdown"))
    /// The track mark alone, 96 x 48 pt at 1x.
    public static let mark = Image("Mark", bundle: .module, label: Text("Trackdown"))
}
